def transform(grid):
    h, w = len(grid), len(grid[0])

    row_divs = [r for r in range(h) if len(set(grid[r])) == 1]
    col_divs = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(n, divs):
        result, start = [], 0
        for d in divs + [n]:
            if start < d:
                result.append((start, d))
            start = d + 1
        return result

    rows = segments(h, row_divs)
    cols = segments(w, col_divs)

    divider_colors = {grid[r][0] for r in row_divs}
    divider_colors.update(grid[0][c] for c in col_divs)

    counts = {}
    for row in grid:
        for value in row:
            if value not in divider_colors:
                counts[value] = counts.get(value, 0) + 1

    background = max(counts, key=counts.get)
    marker = next(value for value in counts if value != background)

    return [
        [
            background if sum(grid[r][c] == marker
                              for r in range(r0, r1)
                              for c in range(c0, c1)) == 1 else 1
            for c0, c1 in cols
        ]
        for r0, r1 in rows
    ]
